import{_ as a,c as n,a0 as e,o as i}from"./chunks/framework.CSihnngI.js";const p="/images/ai/transformer01.png",t="/images/ai/transformer02.png",r="/images/ai/transformer03.png",m=JSON.parse('{"title":"Transformer","description":"","frontmatter":{},"headers":[],"relativePath":"majorTopic/AI/LLM/Transformer.md","filePath":"majorTopic/AI/LLM/Transformer.md","lastUpdated":1783389762000}'),l={name:"majorTopic/AI/LLM/Transformer.md"};function d(o,s,c,h,u,b){return i(),n("div",null,s[0]||(s[0]=[e('<h1 id="transformer" tabindex="-1">Transformer <a class="header-anchor" href="#transformer" aria-label="Permalink to &quot;Transformer&quot;">​</a></h1><h2 id="transformer内部结构" tabindex="-1">Transformer内部结构 <a class="header-anchor" href="#transformer内部结构" aria-label="Permalink to &quot;Transformer内部结构&quot;">​</a></h2><p>整个 NLP 的发展，中间还经历很多很多重要的阶段，例如：</p><ol><li>神经概率语言模型</li><li>卷积神经网络模型</li><li>循环神经网络以及长短期记忆网络</li></ol><p>再到目前最为流行的 Transformer 架构。</p><h2 id="输入和输出" tabindex="-1">输入和输出 <a class="header-anchor" href="#输入和输出" aria-label="Permalink to &quot;输入和输出&quot;">​</a></h2><p>将 LLM 看作是一个黑盒：</p><p>输入称之为提示词（prompt）</p><p><img src="'+p+'" alt="alt text"></p><p>在使用模型的时候，<strong>模型并不是一次性生成所有的文本，而是一次生成一个词元</strong>，如下图所示：</p><p><img src="'+t+'" alt="alt text"></p><p>模型在生成每一个新词元时，都会基于当前的输入序列进行一次 <strong>前向传播（Forward Propagatio）</strong>。</p><p>🙋 什么是前向传播？</p><p>所谓前向传播，是指在神经网络中，从输入层开始，<strong>数据依次通过每一层神经元的计算</strong>，最终产生输出的过程。</p><p>具体步骤：</p><ol><li>输入<strong>嵌入</strong></li><li><strong>多个</strong>神经网络层处理</li><li>输出一个分布，就是所有词元的一个概率</li><li>选一个词生成出来</li></ol><p>而<strong>新生成的词元会被追加到输入序列的末尾</strong>，作为下一步生成的提示词上下文，从而逐步影响整个输出。</p><p><img src="'+r+`" alt="alt text"></p><p>在机器学习中，有一个专门的词用来描述这种使用早期预测来进行后续预测的模型，称之为 <strong>自回归模型</strong>。</p><p>Transformer模型就是一个自回归模型。</p><h2 id="llm内部结构" tabindex="-1">LLM内部结构 <a class="header-anchor" href="#llm内部结构" aria-label="Permalink to &quot;LLM内部结构&quot;">​</a></h2><p>整体来讲分成四大块：</p><img src="https://xiejie-typora.oss-cn-chengdu.aliyuncs.com/2025-05-23-022538.png" alt="image-20250523102537551" style="zoom:50%;"><ol><li>分词器</li><li>嵌入层</li><li>堆叠的Transformer块</li><li>语言建模头</li></ol><h3 id="分词器" tabindex="-1">分词器 <a class="header-anchor" href="#分词器" aria-label="Permalink to &quot;分词器&quot;">​</a></h3><p>模型的第一步是将自然语言输入送入分词器（Tokenizer），将其转换为词元 ID（token IDs）。例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>“我今天很开心”</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>分词：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[&#39;我&#39;, &#39;今天&#39;, &#39;很&#39;, &#39;开&#39;, &#39;心&#39;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>映射为词表中的 ID：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[1, 354, 2764, 77, 199]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="嵌入层" tabindex="-1">嵌入层 <a class="header-anchor" href="#嵌入层" aria-label="Permalink to &quot;嵌入层&quot;">​</a></h3><p>在分词器将文本转换为词元 ID 之后，这些整数 ID 本身并不能直接用于神经网络计算。此时，需要通过嵌入层将每个 ID 映射为一个向量，形成模型的输入表示。</p><p>例如前面得到的词元 ID 列表：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[1, 354, 2764, 77, 199]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>通过嵌入层处理后，得到的嵌入向量：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span> [0.12, -0.87, ...,  0.34],   # 对应 token 1</span></span>
<span class="line"><span> [0.02,  0.45, ..., -0.11],   # 对应 token 354</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [0.76, -0.01, ...,  0.08]    # 对应 token 199</span></span>
<span class="line"><span>]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>每个词元 ID 都会被映射为一个固定维度的向量（例如 768 维或 4096 维），这些向量是模型可学习的参数，在训练过程中会被不断优化。</p><h3 id="堆叠的transformer层" tabindex="-1">堆叠的Transformer层 <a class="header-anchor" href="#堆叠的transformer层" aria-label="Permalink to &quot;堆叠的Transformer层&quot;">​</a></h3><p>Stacked Transformer Blocks，中文译作“堆叠的Transformer块”，这些 Transformer 块是 LLM 的<strong>核心模块</strong>，也是模型理解上下文、捕捉语言结构和语义关系的关键所在。</p><p>每个 Transformer 块内部包含两个主要子模块：</p><ol><li><p><strong>自注意力机制（Self-Attention）</strong>：让每一个词元可以“看见”它前面的所有词元，从而理解上下文。</p><p>例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>“我 今天 很 开心”</span></span>
<span class="line"><span> ↑   ↑  ↑   ↑</span></span>
<span class="line"><span>每个词元都能关注到前面的词元（因自回归模型只看左边）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>比如模型在预测“开心”时，会去关注“我”、“今天”、“很”这些词，理解语义关系。</li><li>注意力机制会为不同词元分配不同的权重。</li></ul></li><li><p><strong>前馈网络（Feed-Forward Network）</strong>：对每个位置上的词元向量单独做非线性变换，提高模型表达能力。</p></li></ol><p>🙋为什么称之为堆叠呢？</p><p>因为 Transformer 块并非一层，而是有多层：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transformer块1 → Transformer块2 → Transformer块3 → Transformer块4 → ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>每一层都会接收上一层的输出，并进一步处理。</p><p>层数越多，大模型就越能够捕捉高层次、复杂的语言结构，也就是说，对输入的文本理解得越准确。</p><p>下表是主流大模型的层数对比：</p><table tabindex="0"><thead><tr><th>模型名称</th><th>参数规模</th><th>Transformer 层数</th><th>备注</th></tr></thead><tbody><tr><td>GPT-2 (small)</td><td>117M</td><td>12</td><td>OpenAI</td></tr><tr><td>GPT-3</td><td>175B</td><td>96</td><td>OpenAI</td></tr><tr><td>GPT-4 (推测)</td><td>~200B+</td><td><strong>96–128（估计）</strong></td><td>可能为 MoE 架构</td></tr><tr><td>Claude 2</td><td>~100B+</td><td>~80–100（推测）</td><td>Anthropic，未公开完整细节</td></tr><tr><td>Claude 3 Opus</td><td>未知</td><td>~128（推测）</td><td>有极强编码能力，多模态支持</td></tr><tr><td>PaLM 2</td><td>340B</td><td>120</td><td>Google</td></tr><tr><td>Gemini 1.5 Pro</td><td>推测 &gt;100B</td><td>未知</td><td>多模态，长上下文（&gt;1M tokens）</td></tr><tr><td>LLaMA 2 (7B)</td><td>7B</td><td>32</td><td>Meta，小模型中非常高效</td></tr><tr><td>LLaMA 2 (70B)</td><td>70B</td><td>80</td><td>Meta</td></tr><tr><td>Mistral (7B)</td><td>7B</td><td>32</td><td>Dense 模型，训练非常高效</td></tr><tr><td>Mixtral (MoE)</td><td>12.9B act.</td><td>32</td><td>激活 2/8 experts（MoE 架构）</td></tr></tbody></table><h3 id="语言建模头" tabindex="-1">语言建模头 <a class="header-anchor" href="#语言建模头" aria-label="Permalink to &quot;语言建模头&quot;">​</a></h3><p>经过多层 Transformer 块处理后，我们会得到每一个位置上的一个高维向量表示。这些向量已经融合了上下文语义信息，接下来需要通过语言建模头（Language Modeling Head）将这些向量转换为我们最终关心的输出：<strong>预测下一个词元</strong>。</p><p>在自回归生成中，<strong>只用最后一个词元位置上的向量</strong>来预测下一个词。</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.87</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.34</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],   ← 代表“我”</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.45</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.77</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],   ← 代表“今天”</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.22</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.63</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.02</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]    ← 代表“很”</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>🙋 为什么只用最后一个词？</p><p>回答：<strong>Transformer 是一个上下文感知的结构</strong>。当我们输入“我今天很”，并经过多层 Transformer 处理后，虽然我们只取了最后一个词“很”对应的向量，但这个向量<strong>已经不是孤立的“很”了</strong>，它已经通过自注意力机制，<strong>融合了前面所有词元的信息</strong>，即“我”、“今天”、“很”的上下文。</p><p><strong>工作流程</strong></p><p>假设有一个词表（语料库）大小为 <code>V = 50,000</code>，Transformer 输出的每个向量是 <code>d = 768</code> 维，那么，语言建模头就是一个维度为：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[768 × 50000]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>的线性变换矩阵，这个矩阵是语言建模头的核心参数，也是参数量最多的一层之一。这里我们把这个矩阵命名为 W。</p><p>接下来下一步是针对 <strong>词表</strong> 里面的每一个词元（50000）进行打分，大致的计算公式如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logits（最终的得分） = z（最后一个词元的向量） · W（线性矩阵）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>z：Transformer 所输出的最后一个词元的嵌入向量，长度为 768</li><li>W：上面所提到的线性变换矩阵</li></ul><p>经过计算后，会得到一个 50000 维的向量数组。这个 50000 维的向量数组里面的每一个值就是词表中词元的得分。</p><p>这个分数仅仅是一个<strong>未归一化的分数</strong>，所谓未归一化，就是指这些分数可以是任何实数（正的、负的、不限制范围），它们<strong>还不是概率</strong>，<strong>还不能直接表示“可能性”</strong>。例如假设我们的词表只有 5 个词，这里就能得到词表中每个词元的分数</p><table tabindex="0"><thead><tr><th>词元</th><th>logits 值</th></tr></thead><tbody><tr><td>开心</td><td>4.2</td></tr><tr><td>累</td><td>2.7</td></tr><tr><td>忙</td><td>1.5</td></tr><tr><td>昨天</td><td>-1.2</td></tr><tr><td>小狗</td><td>-3.5</td></tr></tbody></table><p>最后一步是经过 softmax 转换，目的是将分数转换为概率分布，计算公式如下： $$ \\text{softmax}(logits_i) = \\frac{e^{logits_i}}{\\sum_{j=1}^{n} e^{logits_j}} $$ 整个 softmax 接收上一步拿到的 logits，然后做了两件事：</p><ol><li>先对每个值取指数（确保变成正数）</li><li>再除以总和（确保总和为 1）</li></ol><p>最终，语言建模头工作流程大致如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>z = Transformer_output[-1]  # 取最后一个向量</span></span>
<span class="line"><span>logits = z · W              # [0.1, 0.3, -1.5, 2.6, ...]</span></span>
<span class="line"><span>probs = softmax(logits)     # [0.01, 0.02, 0.00001, 0.85, ...]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="完整流程" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程" aria-label="Permalink to &quot;完整流程&quot;">​</a></h3><p>假设当前输入的是一句未完成的话：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我今天很</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>目标是让大语言模型预测下一个最可能的词元。</p><p>整体流程：</p><p><strong>1. 分词器处理</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[&quot;我&quot;, &quot;今天&quot;, &quot;很&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[1, 354, 2764]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>2. 嵌入层处理</strong></p><p>每个词元 ID 会被映射为高维度向量</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>“我”     → [0.12, -0.87, ..., 0.34]  </span></span>
<span class="line"><span>“今天”   → [-0.11, 0.45, ..., 0.90]  </span></span>
<span class="line"><span>“很”     → [0.20, 0.14, ..., -0.06]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>嵌入向量会形成一个二维数组，维度是 <code>[3, 768]</code>。</p><p><strong>3. Transformer块处理</strong></p><p>经过多层 Transformer 块处理之后，得到的仍然是一个维度为 <code>[3, 768]</code> 的向量数组.</p><p>我们只取最后一个</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>z = [0.12, -0.45, ..., 0.33]  ← 长度为 768</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>虽然这个 z 只是 “很” 这个词元所对应的向量，但是融入了前面词元的意思</p><p><strong>4. 语言建模头计算 logits</strong></p><p>假设语料库里面的词元数量为 50000</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logits = z × W  →  得到一个 [1 × 50000] 的向量</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logits = [0.9, -1.3, 2.1, ..., 5.7]   ← 长度为 50000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>5. softmax 归一化为概率</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  开心: 0.61,</span></span>
<span class="line"><span>  累: 0.12,</span></span>
<span class="line"><span>  忙: 0.08,</span></span>
<span class="line"><span>  郁闷: 0.04,</span></span>
<span class="line"><span>  美丽: 0.02,</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="transformer块" tabindex="-1">Transformer块 <a class="header-anchor" href="#transformer块" aria-label="Permalink to &quot;Transformer块&quot;">​</a></h2><p>整个大语言模型就是由一系列 Transformer 块组成的。每个块处理其输入，然后将处理结果传递给下一块。</p><p>在原始的 Transformer 论文中约为 6 块，现在许多 LLM 中已经超过 100 个了。</p><p><a href="/images/ai/transformer04.png">!Transformer块</a></p><p>每个 Transformer 块由以下两首首尾相接的组件构成：</p><ol><li>自注意力层</li><li>前馈神经网络层</li></ol><p><a href="/images/ai/transformer05.png">!Transformer块</a></p><h3 id="自注意力层" tabindex="-1">自注意力层 <a class="header-anchor" href="#自注意力层" aria-label="Permalink to &quot;自注意力层&quot;">​</a></h3><p>注意力机制帮助模型在处理特定词元的时候 <strong>整合上下文信息</strong>。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>狗追猫，因为它</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>为了预测“它”之后的内容，模型需要知道“它”指代的是什么，是“狗”还是“猫” ？</p><p>注意力机制会将上下文信息添加到“它”这个词元的表示中。</p><p><a href="/images/ai/transformer06.png">!Transformer块</a></p><h4 id="_1-自注意力工作原理" tabindex="-1">1. 自注意力工作原理 <a class="header-anchor" href="#_1-自注意力工作原理" aria-label="Permalink to &quot;1. 自注意力工作原理&quot;">​</a></h4><p>注意力机制会为“它”这个词元计算它与句子中所有其他词元的关联程度。</p><ul><li>它会算出“它”和“狗”有多相关</li><li>“它”和“猫”有多相关</li><li>甚至“它”和“追”“因为”等词之间的关系</li></ul><p>这些相关性通过一个叫做“注意力权重”的分数来表示，<strong>相关性越高，注意力分数越大</strong>。</p><p>下图是另外一段英文提示词文本</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The cat sat on the mat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在自注意力层所生成的权重矩阵图： <a href="/images/ai/transformer07.png">!权重矩阵图</a></p><ul><li><p>横轴（Key）：表示被关注的词，即“被看的对象”；</p></li><li><p>纵轴（Query）：表示当前在处理的词，即“正在看别人的词”；</p></li><li><p>单元格中的值：表示 Query 对应的词对 Key 的关注程度（注意力权重），数值越大，颜色越深。</p></li></ul><p>图中 <code>sat → The</code> 的注意力值是 <code>0.23</code>，意味着在处理 “sat” 这个词时，模型“最关注”的词之一是 “The”；<code>cat → on</code> 的注意力值是 <code>0.21</code>，表示 “cat” 在编码时也部分关注了 “on”。</p><p>回到我们上面“狗追猫”的例子，假设注意力机制得出以下权重：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;它&quot; 对每个词的注意力权重：</span></span>
<span class="line"><span>狗：0.3</span></span>
<span class="line"><span>猫：0.6</span></span>
<span class="line"><span>其他词：0.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>模型“认为”——“它”更可能指的是“猫”。</p><p>那么模型可能就会生成诸如“它吓倒了狗”的后续内容。</p><p>核心：当前词会去关注其它词，并且根据相关性分配权重，从而形成更有语境感知的一个表达。</p><h4 id="_2-多头注意力" tabindex="-1">2. 多头注意力 <a class="header-anchor" href="#_2-多头注意力" aria-label="Permalink to &quot;2. 多头注意力&quot;">​</a></h4><p>所谓多头注意力，指的是模型不只使用一个注意力机制去“看”上下文，而是使用多个注意力头（head）<strong>，每个从不同的角度并行地关注输入中的不同部分。</strong></p><p>一个注意力头只关注一套特定的关系（比如“它”和“狗、猫”之间的关系），但现实语言中的语义很复杂：</p><ul><li>有的头可能专注于语法（主语-动词关系）；</li><li>有的头可能关注指代（“它”指代谁）；</li><li>有的头可能关注情感、时间顺序等……</li></ul><p>多头注意力可以让模型从多个“子空间”中提取信息，从而提升理解力和泛化能力。</p><p>例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>狗追猫，因为它</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>假设有三个注意力头，它们分别学习到了不同的关注模式：</p><ul><li><strong>Head 1：指代消解视角</strong> —— “它”主要关注“猫”，注意力权重为：猫 0.6，狗 0.3，其它词 0.1；</li><li><strong>Head 2：句法结构视角</strong> —— “它”关注“追”这个动词，理解句子动作逻辑；在这个头中，“追”的相关性得分最高</li><li><strong>Head 3：逻辑关系视角</strong> —— “它”关注“因为”，模型试图理解因果结构。在这个头中，“因为”的相关性得分最高</li></ul><p>这些注意力头会各自生成一份“它”的表示，最后再把这些表示<strong>合并起来</strong>，形成一个更加丰富、综合的向量。这个向量同时融合了：</p><ul><li>谁是“它”可能指代的对象，</li><li>“它”参与了什么样的动作，</li><li>“它”在语义上处于怎样的逻辑位置。</li><li>.....</li></ul><p>“它”所对应的向量的含义背后的语义就非常丰富了。这也是为什么前面说 LLM 只需要取最后一个词元来预测下一个词。</p><p>这就像一个小型“专家团队”，每个注意力头都是一个“专家”，专门从某种语言视角来理解当前词元。最终，它们的意见会被整合，让模型拥有更全面的判断力。</p><h3 id="前馈神经网络层" tabindex="-1">前馈神经网络层 <a class="header-anchor" href="#前馈神经网络层" aria-label="Permalink to &quot;前馈神经网络层&quot;">​</a></h3><p>自注意力机制让每个词元在上下文中“看别人”，整合其他词的信息。但仅靠这些信息还不够，Transformer 还需要进一步让每个词<strong>自己思考、提炼、变换</strong>。这个任务，就交给了前馈神经网络层（Feed Forward Neural Network，简称 FFN）。</p><p>前馈神经网络的特别之处在于：它不会“看别人”，只处理<strong>自己</strong>。</p><p>🙋怎么处理？</p><p>它是<strong>对每一个词元单独做的一次变换处理</strong>。你可以理解为：自注意力层结束后，每个词元都从“他人”那里学到了不少内容；接下来轮到它自己好好消化一遍。</p><p>🙋如何消化？</p><p>其实就是把词元当前的表示向量送入一个小型的神经网络中，通常会包含两层线性变换和一个非线性激活函数，流程如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 → 线性变换（升维） → 激活函数 → 线性变换（降维） → 输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>再具体一点的话，这一过程可以用公式表示为： $$ FFN(x)=GELU(xW1+b1)W2+b2 $$ 其中 GELU 是一种激活函数，负责加入“非线性思考能力”。</p><p>例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>狗追猫，因为它</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在经过自注意力机制之后，“它”这个词已经看向了上下文，并初步融合了来自“猫”“狗”等词的语义信息。</p><p>但是，这样的表示只是“初加工品”。模型还需要进一步处理它，让它具备更强的语义表达能力和推理能力。这时，“它”的向量就会被送入前馈网络中：</p><ul><li>前馈层会先把这个向量升维到一个更高维度（比如从 768 维扩展到 3072 维）；</li><li>接着，经过 GELU 激活函数进行非线性处理；</li><li>然后再降维回原来的大小，形成一个新的、更复杂的向量表示。</li></ul><p>这个新表示就是“它”这个词元的升级版本，里面包含了模型对“它”这个词更深层的理解，可以帮助模型提取出更适合判断行为、情感、逻辑的语义特征。最终形成的向量将送入下一层 Transformer，继续处理。</p><p>因此，前馈层也是非常重要的一层，看起来只是“对每个词做了一遍变换”，但它非常关键。如果 Transformer 只有注意力层没有前馈层，那它就像是一个只会模仿别人的人，不会自己总结、推理和表达。如果说自注意力阶段是“看外部世界”，那么前馈网络阶段就是“闭上眼睛思考自己”。</p><hr>`,149)]))}const k=a(l,[["render",d]]);export{m as __pageData,k as default};
